using StremioXboxPrototype.Models;
using StremioXboxPrototype.Services;
using System;
using System.Threading.Tasks;
using Windows.System;
using Windows.UI.Xaml;
using Windows.UI.Xaml.Controls;
using Windows.UI.Xaml.Input;
using Windows.UI.Xaml.Media;

namespace StremioXboxPrototype;
public sealed partial class MainPage : Page
{
    private readonly ISettingsService _settings = new SettingsService();
    private readonly IServerService _server = new ServerService();
    private readonly AppSettings _appSettings = new();
    private string _currentPage = "Home";
    public MainPage() { InitializeComponent(); Loaded += async (_, __) => { var loaded = await _settings.LoadAsync(); CopySettings(loaded, _appSettings); ShowPage("Home"); }; }
    private static void CopySettings(AppSettings from, AppSettings to) { to.AutoplayNextEpisode = from.AutoplayNextEpisode; to.SkipIntro = from.SkipIntro; to.DefaultQuality = from.DefaultQuality; to.PreferredCodec = from.PreferredCodec; to.DynamicRange = from.DynamicRange; to.SubtitleSize = from.SubtitleSize; }
    private void Navigate_Click(object sender, RoutedEventArgs e) => ShowPage((string)((Button)sender).Tag);
    private void OnKeyDown(object sender, KeyRoutedEventArgs e) { if (e.Key == VirtualKey.GamepadY) { ShowPage("Search"); GlobalSearch.Focus(FocusState.Programmatic); } else if (e.Key == VirtualKey.GamepadB && _currentPage != "Home") ShowPage("Home"); }
    private void Search_KeyDown(object sender, KeyRoutedEventArgs e) { if (e.Key == VirtualKey.Enter) ShowPage("Search", GlobalSearch.Text); }
    private void Refresh_Click(object sender, RoutedEventArgs e) => ShowToast("Refresh requested. Provider data will be refreshed when a catalog adapter is configured.");
    private void ShowPage(string page, string query = "") { _currentPage = page; ContentHost.Children.Clear(); var title = new TextBlock { Text = page, FontSize = 40, FontWeight = Windows.UI.Text.FontWeights.SemiBold, Foreground = (Brush)Application.Current.Resources["TextPrimaryBrush"] }; ContentHost.Children.Add(title); ContentHost.Children.Add(new TextBlock { Text = Subtitle(page), FontSize = 18, Foreground = (Brush)Application.Current.Resources["TextSecondaryBrush"], Margin = new Thickness(0, 0, 0, 14) }); switch (page) { case "Home": Home(); break; case "Discover": Discover(); break; case "Library": Library(); break; case "Add-ons": Addons(); break; case "Search": Search(query); break; case "Settings": Settings(); break; case "Server": Server(); break; case "Diagnostics": Diagnostics(); break; case "Playback Lab": PlaybackLab(); break; case "Profile": Profile(); break; default: Empty("This screen is not available."); break; } }
    private static string Subtitle(string p) => p switch { "Home" => "Pick up where you left off or find your next favourite", "Discover" => "Browse collections, genres and trending picks", "Library" => "Your watchlist, history and saved items", "Add-ons" => "Manage sources, extensions and community integrations", "Search" => "Find movies, series and add-ons", "Playback Lab" => "Test playback, codecs and stream behavior", "Server" => "Connect and manage your playback server", "Diagnostics" => "Inspect system health and troubleshoot playback", "Settings" => "Customize playback, appearance and app behavior", _ => "Your profile and playback preferences" };
    private TextBlock Text(string value, double size = 16, bool primary = true) => new TextBlock { Text = value, FontSize = size, Foreground = (Brush)Application.Current.Resources[primary ? "TextPrimaryBrush" : "TextSecondaryBrush"], TextWrapping = TextWrapping.Wrap };
    private Border Panel(UIElement child) => new Border { Background = (Brush)Application.Current.Resources["SurfaceBrush"], BorderBrush = new SolidColorBrush(Windows.UI.Color.FromArgb(255, 55, 57, 110)), BorderThickness = new Thickness(1), CornerRadius = new CornerRadius(12), Padding = new Thickness(18), Margin = new Thickness(0, 6, 0, 6), Child = child };
    private void Empty(string message) { ContentHost.Children.Add(Panel(Text(message, 17, false))); }
    private void ShowToast(string message) { ContentHost.Children.Insert(2, Panel(Text(message, 15, false))); }
    private void Home()
    {
        var banner = new Grid(); banner.ColumnDefinitions.Add(new ColumnDefinition()); banner.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); banner.Children.Add(Text("⚠  Your playback server is offline. You can still browse or try reconnecting.", 16, false)); var reconnect = new Button { Content = "Reconnect", Style = (Style)Application.Current.Resources["FocusButton"] }; reconnect.Click += async (_, __) => await Reconnect(); Grid.SetColumn(reconnect, 1); banner.Children.Add(reconnect); ContentHost.Children.Add(Panel(banner)); Row("Continue Watching", "Nova Tide", "The Far Reaches", "Split Horizon", "The Deeper", "Velvet Skies"); Row("Popular Movies", "Orbital Fall", "Midnight District", "Silent Meadow", "Iron Harbor", "Beechtree Ritual", "Sparrow", "Frozen Currents", "Red Expanse"); Row("Popular Series", "Hollow Pines", "Citadel Falls", "Blackwater", "Parallel Lives", "The Kingsway", "Emberwild", "Subject Eleven", "Dustborn");
    }
    private void Row(string title, params string[] items)
    {
        var root = new StackPanel { Margin = new Thickness(0, 10, 0, 0) }; var header = new Grid(); header.ColumnDefinitions.Add(new ColumnDefinition()); header.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); header.Children.Add(Text(title, 24)); var see = new Button { Content = "See all  ›", Style = (Style)Application.Current.Resources["FocusButton"] }; Grid.SetColumn(see, 1); header.Children.Add(see); root.Children.Add(header); var list = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var item in items) list.Children.Add(MediaCard(item)); root.Children.Add(list); ContentHost.Children.Add(root);
    }
    private Button MediaCard(string title) { var p = new StackPanel(); p.Children.Add(new Border { Height = 180, Background = new LinearGradientBrush { GradientStops = { new GradientStop { Color = Windows.UI.Color.FromArgb(255, 50, 43, 114), Offset = 0 }, new GradientStop { Color = Windows.UI.Color.FromArgb(255, 12, 39, 72), Offset = 1 } } }, CornerRadius = new CornerRadius(8), Child = new TextBlock { Text = "✦", FontSize = 44, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center, Foreground = new SolidColorBrush(Windows.UI.Color.FromArgb(255, 142, 111, 255)) } }); p.Children.Add(Text(title, 15)); p.Children.Add(Text("2026  •  1h 55m  •  Sci-Fi", 13, false)); return new Button { Content = p, Width = 178, HorizontalContentAlignment = HorizontalAlignment.Stretch, VerticalContentAlignment = VerticalAlignment.Stretch, Style = (Style)Application.Current.Resources["FocusButton"], Tag = title, Margin = new Thickness(4, 4, 8, 4) }; }
    private void Discover() { var filters = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var f in new[] { "Trending", "New Releases", "Action", "Drama", "Sci-Fi", "Family", "Documentary" }) filters.Children.Add(new Button { Content = f, Style = (Style)Application.Current.Resources["FocusButton"] }); ContentHost.Children.Add(filters); var hero = new StackPanel(); hero.Children.Add(Text("FEATURED", 13, false)); hero.Children.Add(Text("STARFALL", 43)); hero.Children.Add(Text("A crew of explorers uncovers a dormant civilisation on a distant moon, igniting a race against time.", 17, false)); var actions = new StackPanel { Orientation = Orientation.Horizontal }; actions.Children.Add(new Button { Content = "▶  Watch Now", Style = (Style)Application.Current.Resources["FocusButton"] }); actions.Children.Add(new Button { Content = "ⓘ  More Info", Style = (Style)Application.Current.Resources["FocusButton"] }); hero.Children.Add(actions); ContentHost.Children.Add(Panel(hero)); Row("Trending Now", "Neon Harbor", "Ashen Paths", "Lumen Expanse", "Violet Crown", "Breaking Tide", "Emberfall", "Glass Valley"); Row("Recommended For You", "Solace", "The Foundry", "Cinder Skies", "Quiet Machines", "Evergreen", "Shattered Horizon"); }
    private void Library() { var tabs = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var t in new[] { "▶  Continue Watching", "▱  Watchlist", "◷  History", "⇩  Downloads" }) tabs.Children.Add(new Button { Content = t, Style = (Style)Application.Current.Resources["FocusButton"] }); ContentHost.Children.Add(tabs); Row("Continue Watching", "Nova Tide", "The Far Reaches", "Split Horizon", "The Deeper", "Velvet Skies"); Row("Watchlist", "Orbital Fall", "Midnight District", "Silent Meadow", "Iron Harbor", "Sparrow"); Row("Recently Watched", "Hollow Pines", "Citadel Falls", "Blackwater", "Parallel Lives", "The Kingsway"); }
    private void Addons() { var stats = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var s in new[] { "▣  Installed Add-ons\n6 enabled", "⇩  Updates Available\n3 ready to install", "⌁  Connected Sources\nUnavailable" }) stats.Children.Add(Panel(Text(s, 18))); ContentHost.Children.Add(stats); ContentHost.Children.Add(Text("Installed Add-ons", 24)); foreach (var a in new[] { "Nebula Streams|Discover and stream from community sources across the galaxy.|Enabled", "Atlas Metadata|Enrich your library with artwork and details.|Enabled", "Cloud Sync|Sync library, settings and watch progress.|Enabled", "UI Themes|Custom themes and background packs.|Disabled" }) { var parts = a.Split('|'); var row = new Grid(); row.ColumnDefinitions.Add(new ColumnDefinition()); row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto }); var copy = new StackPanel(); copy.Children.Add(Text(parts[0], 18)); copy.Children.Add(Text(parts[1], 15, false)); copy.Children.Add(Text("●  " + parts[2], 14, false)); row.Children.Add(copy); var b = new Button { Content = parts[2] == "Enabled" ? "Disable" : "Enable", Style = (Style)Application.Current.Resources["FocusButton"] }; Grid.SetColumn(b, 1); row.Children.Add(b); ContentHost.Children.Add(Panel(row)); } ContentHost.Children.Add(Text("Browse Add-ons", 24)); Row("", "Orion Scraper", "Meadow Subtitles", "Lumen Social", "Flow Manager", "Echo Hub"); }
    private void Search(string query) { var input = new TextBox { Text = query, PlaceholderText = "Search movies, series and add-ons", FontSize = 24, Background = (Brush)Application.Current.Resources["SurfaceBrush"], Foreground = (Brush)Application.Current.Resources["TextPrimaryBrush"], BorderBrush = (Brush)Application.Current.Resources["AccentBrush"], Padding = new Thickness(18, 12, 18, 12), CornerRadius = new CornerRadius(12) }; input.KeyDown += async (_, e) => { if (e.Key == VirtualKey.Enter) { await Task.Delay(300); ShowToast("No provider configured. Connect a Stremio-compatible catalog service to return results."); } }; ContentHost.Children.Add(input); ContentHost.Children.Add(Text("Recent searches", 16, false)); var chips = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var c in new[] { "space", "the reaches", "nova tide", "sci-fi" }) chips.Children.Add(new Button { Content = c, Style = (Style)Application.Current.Resources["FocusButton"] }); ContentHost.Children.Add(chips); if (!string.IsNullOrWhiteSpace(query)) Empty("Searching is debounced and cancellation-aware. No catalog provider is configured yet."); else Empty("Start typing to search catalog, series and add-ons."); }
    private void Settings() { var categories = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var c in new[] { "General", "Playback", "Appearance", "Subtitles", "Audio", "Controller", "Privacy", "Developer" }) categories.Children.Add(new Button { Content = c, Style = (Style)Application.Current.Resources["FocusButton"] }); ContentHost.Children.Add(categories); ContentHost.Children.Add(Text("Playback Settings", 25)); Toggle("Autoplay next episode", _appSettings.AutoplayNextEpisode, v => _appSettings.AutoplayNextEpisode = v); Choice("Default quality", new[] { "Auto", "4K", "1080p", "720p" }, _appSettings.DefaultQuality, v => _appSettings.DefaultQuality = v); Choice("Preferred codec", new[] { "Auto", "HEVC", "H.264", "AV1" }, _appSettings.PreferredCodec, v => _appSettings.PreferredCodec = v); Choice("Dynamic range", new[] { "SDR", "HDR", "Dolby Vision" }, _appSettings.DynamicRange, v => _appSettings.DynamicRange = v); Choice("Subtitle size", new[] { "Small", "Medium", "Large" }, _appSettings.SubtitleSize, v => _appSettings.SubtitleSize = v); Toggle("Skip intro", _appSettings.SkipIntro, v => _appSettings.SkipIntro = v); var save = new Button { Content = "Save Changes", Style = (Style)Application.Current.Resources["FocusButton"] }; save.Click += async (_, __) => { await _settings.SaveAsync(_appSettings); ShowToast("Settings saved on this device."); }; ContentHost.Children.Add(save); }
    private void Toggle(string label, bool value, Action<bool> changed) { var t = new ToggleSwitch { Header = label, IsOn = value, OnContent = "On", OffContent = "Off", Foreground = (Brush)Application.Current.Resources["TextPrimaryBrush"], Margin = new Thickness(10) }; t.Toggled += (_, __) => changed(t.IsOn); ContentHost.Children.Add(Panel(t)); }
    private void Choice(string label, string[] choices, string current, Action<string> changed) { var box = new ComboBox { Header = label, ItemsSource = choices, SelectedItem = current, Foreground = (Brush)Application.Current.Resources["TextPrimaryBrush"], Margin = new Thickness(10), MinWidth = 300 }; box.SelectionChanged += (_, __) => { if (box.SelectedItem is string v) changed(v); }; ContentHost.Children.Add(Panel(box)); }
    private void Server() { Empty("Connection status: Offline. Browsing is available, but playback requires a connected server."); var url = new TextBox { PlaceholderText = "Server URL (https://server.example:8096)", Background = (Brush)Application.Current.Resources["SurfaceBrush"], Foreground = (Brush)Application.Current.Resources["TextPrimaryBrush"], Padding = new Thickness(14), CornerRadius = new CornerRadius(8) }; ContentHost.Children.Add(url); var actions = new StackPanel { Orientation = Orientation.Horizontal }; var test = new Button { Content = "Test Connection", Style = (Style)Application.Current.Resources["FocusButton"] }; test.Click += async (_, __) => { var found = await _server.TestAsync(url.Text, default); ShowToast(found is null ? "Enter a valid HTTP or HTTPS server URL." : "Endpoint saved as not tested. Connect an adapter to verify reachability."); }; actions.Children.Add(test); actions.Children.Add(new Button { Content = "Save", Style = (Style)Application.Current.Resources["FocusButton"] }); ContentHost.Children.Add(actions); ContentHost.Children.Add(Text("Recent Servers", 24)); Empty("No successful server connections are stored on this device."); ContentHost.Children.Add(Text("Local Discovery", 24)); Empty("Local server discovery is unavailable until a discovery adapter is configured."); }
    private void Diagnostics() { var stats = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var s in new[] { "⌁  Network\nUnavailable", "▤  Storage\nUnavailable", "▣  Decoder\nUnavailable", "▥  Memory\nUnavailable", "▥  Frame Drops\nUnavailable" }) stats.Children.Add(Panel(Text(s, 16))); ContentHost.Children.Add(stats); ContentHost.Children.Add(Text("Recent Events", 24)); Empty("No diagnostic events recorded in this session."); ContentHost.Children.Add(Text("System Checks", 24)); foreach (var check in new[] { "Internet Connection", "Server Reachability", "DRM (PlayReady)", "Subtitle Renderer", "Audio Output" }) ContentHost.Children.Add(Panel(Text(check + "\nNot tested", 16, false))); var run = new Button { Content = "▶  Run Diagnostics", Style = (Style)Application.Current.Resources["FocusButton"] }; run.Click += (_, __) => ShowToast("Diagnostics are intentionally unavailable until runtime probes are implemented; no synthetic hardware values are shown."); ContentHost.Children.Add(run); }
    private void PlaybackLab() { var cards = new StackPanel { Orientation = Orientation.Horizontal }; foreach (var s in new[] { "▣  Codec Support\nUnavailable", "HDR  HDR\nUnavailable", "♬  Audio Output\nUnavailable", "▥  Adaptive Bitrate\nUnavailable" }) cards.Children.Add(Panel(Text(s, 16))); ContentHost.Children.Add(cards); var test = new Border { Height = 300, Background = new LinearGradientBrush { GradientStops = { new GradientStop { Color = Windows.UI.Color.FromArgb(255, 22, 36, 82), Offset = 0 }, new GradientStop { Color = Windows.UI.Color.FromArgb(255, 5, 8, 23), Offset = 1 } } }, CornerRadius = new CornerRadius(12), Child = Text("Test Stream\nConnect a trusted test-stream URL before playback can start.\nCapabilities are verified at runtime and never assumed.", 20, false) }; ContentHost.Children.Add(test); Toggle("Auto bitrate (ABR)", true, _ => { }); Toggle("Prefer HEVC", false, _ => { }); Toggle("Prefer AV1", false, _ => { }); Choice("Max resolution", new[] { "Auto", "4K (2160p)", "1080p", "720p" }, "Auto", _ => { }); Choice("Buffer mode", new[] { "Balanced (Default)", "Conservative", "Aggressive" }, "Balanced (Default)", _ => { }); Row("Test Streams", "4K HDR Demo", "Low Bandwidth Test", "Subtitle Sync Test", "Multi-audio Test"); }
    private void Profile() { ContentHost.Children.Add(Panel(Text("◉  Local Profile\n\nServer state: Offline\nLibrary statistics: Unavailable until a catalog provider is configured.\n\nProfile support is designed for future multi-profile storage.", 20))); ContentHost.Children.Add(new Button { Content = "Sign out", Style = (Style)Application.Current.Resources["FocusButton"] }); }
    private async Task Reconnect() { await Task.Delay(200); ShowToast("No saved server endpoint. Open Server to add and test a URL."); }
}
